(function () {
  'use strict';

  const STORAGE_KEY = 'seed_todo_app_v3';
  const MAX_LEVEL = 4;

  // Placeholder replaced with real character Base64 PNG Data URIs during bundling
  const CHAR_SPRITES = {
  "stuck": "data:image/png;base64,",
  "done": "data:image/png;base64,",
  "in_progress": "data:image/png;base64,",
  "empty": "data:image/png;base64,"
};

  const STATUS_LABELS = {
    empty: '未开始',
    in_progress: '进行中',
    done: '已完成',
    stuck: '卡住了'
  };

  function createInitialState() {
    return {
      motto: '问鼎巅峰之路',
      rootText: '',
      focusMode: false,
      nodes: [],
      memories: []
    };
  }

  let appState = loadState();
  let currentView = 'canvas';
  let listFilter = 'all';
  let memoryFilter = 'all'; // 'all' | 'active' | 'ended'

  const isMobileViewport = () => window.innerWidth <= 768;

  let camera = {
    x: 0,
    y: 0,
    scale: isMobileViewport() ? 0.78 : 1
  };
  const MIN_SCALE = 0.35;
  const MAX_SCALE = 2.2;

  let selectedNodeId = null;
  let activePopoverNodeId = null;
  let activeContextNodeId = null;
  let pendingAddParentId = null;
  let pendingDeleteNodeId = null;
  let pendingEndNodeId = null;
  let pendingDeleteMemoryId = null;
  let newlyAnimatedNodeIds = new Set();
  const expandedMemorySubtrees = new Set();

  // =========================================================
  // UTILITIES: CLONE & PATH HELPERS
  // =========================================================
  function deepClone(obj) {
    return JSON.parse(JSON.stringify(obj));
  }

  function findNodePathNames(targetId, list = appState.nodes, acc = []) {
    for (const n of list) {
      if (n.id === targetId) return acc;
      if (n.children && n.children.length > 0) {
        const res = findNodePathNames(targetId, n.children, [...acc, n.text]);
        if (res) return res;
      }
    }
    return null;
  }

  // =========================================================
  // PERSISTENCE, MIGRATION & INDEPENDENT MEMORY SNAPSHOTS
  // =========================================================
  function migrateState(rawState) {
    const state = {
      motto: typeof rawState.motto === 'string' && rawState.motto.trim() ? rawState.motto : '问鼎巅峰之路',
      rootText: typeof rawState.rootText === 'string' ? rawState.rootText : '',
      focusMode: Boolean(rawState.focusMode),
      nodes: Array.isArray(rawState.nodes) ? rawState.nodes : [],
      memories: Array.isArray(rawState.memories) ? rawState.memories : []
    };

    recalculateTreeStatuses(state.nodes);
    syncDoneSnapshotsToMemories(state);
    return state;
  }

  function loadState() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && Array.isArray(parsed.nodes)) {
          const migrated = migrateState(parsed);
          saveState(migrated, false);
          return migrated;
        }
      }
    } catch (e) {
      console.warn('Failed to load state from localStorage:', e);
    }
    const init = createInitialState();
    saveState(init, false);
    return init;
  }

  function saveState(stateToSave = appState, syncMemories = true) {
    try {
      recalculateTreeStatuses(stateToSave.nodes);
      if (syncMemories) {
        syncDoneSnapshotsToMemories(stateToSave);
      }
      localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
    } catch (e) {
      console.warn('Failed to save state:', e);
    }
  }

  /**
   * Synchronizes all currently 'done' nodes on the tree into appState.memories.
   * - If a node becomes 'done' for the first time, creates a snapshot.
   * - Never deletes or overwrites completedAt if the node was previously recorded;
   *   never deletes memories if a node is later deleted or switched back to non-done.
   */
  function syncDoneSnapshotsToMemories(stateObj = appState) {
    if (!Array.isArray(stateObj.memories)) {
      stateObj.memories = [];
    }

    (function walk(list, pathNames) {
      for (const node of list) {
        if (node.status === 'done') {
          const pathStr = pathNames.length > 0 ? pathNames.join(' / ') : '第 1 层主干任务';
          const existing = stateObj.memories.find((m) => m.id === node.id);
          if (!existing) {
            stateObj.memories.push({
              id: node.id,
              text: node.text,
              path: pathStr,
              level: node.level,
              parentId: node.parentId || 'root',
              completedAt: node.completedAt || node.updatedAt || node.createdAt || Date.now(),
              ended: false,
              endedAt: null,
              archivedWithParentId: null,
              nodeSnapshot: deepClone(node)
            });
          } else if (!existing.ended) {
            existing.text = node.text;
            existing.path = pathStr;
            existing.level = node.level;
            existing.parentId = node.parentId || 'root';
            existing.nodeSnapshot = deepClone(node);
          }
        }
        if (node.children && node.children.length > 0) {
          walk(node.children, [...pathNames, node.text]);
        }
      }
    })(stateObj.nodes, []);
  }

  function recalculateTreeStatuses(nodeList) {
    nodeList.forEach((node, idx) => {
      if (node.level === 1) {
        node.code = String(idx + 1).padStart(2, '0');
      }
      if (!node.children || node.children.length === 0) {
        node.children = [];
        node.hasStuckDescendant = false;
        node.progress = {
          current: node.status === 'done' ? 1 : 0,
          total: 1
        };
      } else {
        node.children.forEach((child, cIdx) => {
          child.level = Math.min(MAX_LEVEL, node.level + 1);
          child.parentId = node.id;
          child.code = `${node.code}.${cIdx + 1}`;
        });
        recalculateTreeStatuses(node.children);

        const total = node.children.length;
        const doneCount = node.children.filter((c) => c.status === 'done').length;
        const activeOrDoneCount = node.children.filter(
          (c) => c.status === 'in_progress' || c.status === 'done'
        ).length;
        const anyStuck = node.children.some(
          (c) => c.status === 'stuck' || c.hasStuckDescendant
        );

        const prevStatus = node.status;
        node.progress = { current: doneCount, total };
        node.hasStuckDescendant = anyStuck;

        if (doneCount === total && total > 0) {
          node.status = 'done';
          if (prevStatus !== 'done' && !node.completedAt) {
            node.completedAt = Date.now();
          }
        } else if (activeOrDoneCount > 0) {
          node.status = 'in_progress';
          node.completedAt = null;
        } else {
          node.status = 'empty';
          node.completedAt = null;
        }
      }
    });
  }

  function findNodeById(id, list = appState.nodes, parent = null) {
    for (let i = 0; i < list.length; i++) {
      const item = list[i];
      if (item.id === id) {
        return { node: item, parent, list, index: i };
      }
      if (item.children && item.children.length > 0) {
        const found = findNodeById(id, item.children, item);
        if (found) return found;
      }
    }
    return null;
  }

  function countDescendants(node) {
    if (!node.children || node.children.length === 0) return 0;
    let count = node.children.length;
    for (const child of node.children) {
      count += countDescendants(child);
    }
    return count;
  }

  function countVisibleDescendants(node) {
    if (!node.expanded || !node.children || node.children.length === 0) return 0;
    let count = node.children.length;
    for (const child of node.children) {
      count += countVisibleDescendants(child);
    }
    return count;
  }

  // =========================================================
  // RADIAL TREE LAYOUT ENGINE (SUBTREE WEIGHT + COLLISION SOLVER)
  // =========================================================
  function computeSubtreeWeights(node) {
    const totalDesc = countDescendants(node);
    const visDesc = countVisibleDescendants(node);

    if (!node.expanded || !node.children || node.children.length === 0) {
      node._subtreeWeight = 1 + Math.min(0.45, totalDesc * 0.08);
      node._visibleSubtreeCount = 1;
      return node._subtreeWeight;
    }

    let childrenWeightSum = 0;
    let visCountSum = 1;
    for (const child of node.children) {
      childrenWeightSum += computeSubtreeWeights(child);
      visCountSum += child._visibleSubtreeCount;
    }

    node._visibleSubtreeCount = visCountSum;
    node._subtreeWeight = Math.max(
      1.4,
      childrenWeightSum * 1.15 + visDesc * 0.35 + totalDesc * 0.1
    );
    return node._subtreeWeight;
  }

  function computeDynamicTreeLayout() {
    const l1Nodes = appState.nodes;
    if (!l1Nodes || l1Nodes.length === 0) return;

    let anyExpanded = false;
    l1Nodes.forEach((n, idx) => {
      computeSubtreeWeights(n);
      if (n.expanded && n.children && n.children.length > 0) {
        anyExpanded = true;
      }
      if (!n.side) {
        n.side = idx < 6 || idx % 2 === 0 ? 'left' : 'right';
      }
      if (typeof n.orderIndex !== 'number') {
        n.orderIndex = idx;
      }
    });

    const leftNodes = l1Nodes
      .filter((n) => n.side === 'left')
      .sort((a, b) => (a.orderIndex ?? 99) - (b.orderIndex ?? 99));
    const rightNodes = l1Nodes
      .filter((n) => n.side !== 'left')
      .sort((a, b) => (a.orderIndex ?? 99) - (b.orderIndex ?? 99));

    const leftTotalWeight = leftNodes.reduce((acc, n) => acc + n._subtreeWeight, 0) || 1;
    const rightTotalWeight = rightNodes.reduce((acc, n) => acc + n._subtreeWeight, 0) || 1;

    const leftHalfSpan = anyExpanded
      ? Math.min(Math.PI * 0.46, Math.PI * (0.35 + leftTotalWeight * 0.008))
      : Math.PI * 0.34;
    const rightHalfSpan = anyExpanded
      ? Math.min(Math.PI * 0.46, Math.PI * (0.35 + rightTotalWeight * 0.008))
      : Math.PI * 0.34;

    layoutHemisphere(
      leftNodes,
      leftTotalWeight,
      -Math.PI + leftHalfSpan,
      -Math.PI - leftHalfSpan,
      anyExpanded
    );

    layoutHemisphere(
      rightNodes,
      rightTotalWeight,
      -rightHalfSpan,
      rightHalfSpan,
      anyExpanded
    );

    const { visibleNodes } = getVisibleNodesAndLinks();
    resolveGlobalCanvasCollisions(visibleNodes);
  }

  function layoutHemisphere(nodes, totalWeight, startAngle, endAngle, anyExpanded) {
    if (nodes.length === 0) return;
    const totalSpan = endAngle - startAngle;
    const dir = totalSpan >= 0 ? 1 : -1;
    const absTotalSpan = Math.abs(totalSpan);

    let cursor = startAngle;

    nodes.forEach((node, idx) => {
      const share = node._subtreeWeight / totalWeight;
      const sectorSpan = absTotalSpan * share;
      const sectorStart = cursor;
      const sectorEnd = cursor + dir * sectorSpan;
      const midAngle = (sectorStart + sectorEnd) * 0.5;
      cursor = sectorEnd;

      const isExpandedParent = node.expanded && node.children && node.children.length > 0;
      let rX = 335;
      let rY = 238;

      if (!anyExpanded) {
        const stagger = idx % 2 === 1 ? 1.16 : 0.94;
        rX = 345 * stagger;
        rY = 225 * stagger;
      } else {
        const stagger = isExpandedParent ? 1.04 : idx % 2 === 1 ? 1.12 : 0.92;
        rX = 330 * stagger;
        rY = 255 * stagger;
      }

      if (!node._userDragged) {
        node.position = {
          x: Math.round(Math.cos(midAngle) * rX),
          y: Math.round(Math.sin(midAngle) * rY)
        };
      }

      if (isExpandedParent) {
        const outwardAngle = Math.atan2(node.position.y, node.position.x);
        layoutSubtreeChildren(node, outwardAngle, Math.max(sectorSpan, 0.42));
      }
    });
  }

  function layoutSubtreeChildren(parentNode, parentOutwardAngle, allocatedSectorSpan) {
    const children = parentNode.children;
    if (!children || children.length === 0) return;

    const k = children.length;
    const totalChildWeight =
      children.reduce((acc, c) => acc + (c._subtreeWeight || 1), 0) || 1;

    const minSpanForChildren = Math.min(
      Math.PI * 0.88,
      Math.max(allocatedSectorSpan * 1.15, (k - 1) * 0.34 + 0.18 * totalChildWeight)
    );

    const minChordSpacing = 158;
    const baseStepDist = parentNode.level === 1 ? 186 : parentNode.level === 2 ? 172 : 162;
    const arcBasedDist =
      k > 1
        ? (totalChildWeight * minChordSpacing * 0.78) / Math.max(minSpanForChildren, 0.55)
        : baseStepDist;
    const stepRadius = Math.max(baseStepDist, Math.min(310, arcBasedDist));

    let angleCursor = parentOutwardAngle - minSpanForChildren * 0.5;

    children.forEach((child, idx) => {
      const w = child._subtreeWeight || 1;
      const childSpan = minSpanForChildren * (w / totalChildWeight);
      const childAngle =
        k === 1 ? parentOutwardAngle : angleCursor + childSpan * 0.5;
      angleCursor += childSpan;

      const radialStagger = k >= 3 ? (idx % 2 === 1 ? 38 : 0) : 0;
      const dist = stepRadius + radialStagger;

      if (!child._userDragged) {
        child.position = {
          x: Math.round(parentNode.position.x + Math.cos(childAngle) * dist),
          y: Math.round(parentNode.position.y + Math.sin(childAngle) * dist)
        };
      }

      if (child.expanded && child.children && child.children.length > 0) {
        const nextOutward = Math.atan2(
          child.position.y - parentNode.position.y * 0.35,
          child.position.x - parentNode.position.x * 0.35
        );
        layoutSubtreeChildren(child, nextOutward, Math.max(childSpan, 0.38));
      }
    });
  }

  function getNodeVisualRadius(node) {
    const baseR = node.level === 1 ? 58 : node.level === 2 ? 53 : node.level === 3 ? 49 : 46;
    return {
      rx: baseR + 18,
      ry: baseR + 28
    };
  }

  function resolveGlobalCanvasCollisions(visibleNodes) {
    const n = visibleNodes.length;
    if (n === 0) return;

    const ROOT_CLEARANCE_X = 228;
    const ROOT_CLEARANCE_Y = 224;
    const MAX_ITER = 140;

    for (let iter = 0; iter < MAX_ITER; iter++) {
      let maxOverlap = 0;

      for (let i = 0; i < n; i++) {
        const u = visibleNodes[i];
        const dx = u.position.x;
        const dy = u.position.y;
        const normDist = Math.hypot(dx / ROOT_CLEARANCE_X, dy / ROOT_CLEARANCE_Y);
        if (normDist < 1) {
          const angle = Math.atan2(dy || 1, dx || -1);
          const pushFactor = 1.03 - normDist;
          const shiftX = Math.cos(angle) * ROOT_CLEARANCE_X * pushFactor;
          const shiftY = Math.sin(angle) * ROOT_CLEARANCE_Y * pushFactor;
          u.position.x += shiftX;
          u.position.y += shiftY;
          shiftSubtree(u, shiftX * 0.6, shiftY * 0.6);
          maxOverlap = Math.max(maxOverlap, pushFactor * 100);
        }
      }

      for (let i = 0; i < n; i++) {
        const a = visibleNodes[i];
        const ra = getNodeVisualRadius(a);

        for (let j = i + 1; j < n; j++) {
          const b = visibleNodes[j];
          const rb = getNodeVisualRadius(b);

          const minSepX = ra.rx + rb.rx;
          const minSepY = ra.ry + rb.ry;

          const dx = b.position.x - a.position.x;
          const dy = b.position.y - a.position.y;

          const nx = dx / minSepX;
          const ny = dy / minSepY;
          const normDist = Math.hypot(nx, ny);

          if (normDist < 1) {
            const overlapRatio = 1 - normDist;
            maxOverlap = Math.max(maxOverlap, overlapRatio * minSepX);

            let ux, uy;
            if (normDist > 0.001) {
              ux = nx / normDist;
              uy = ny / normDist;
            } else {
              const fallbackAngle = Math.atan2(b.position.y, b.position.x) + 0.35;
              ux = Math.cos(fallbackAngle);
              uy = Math.sin(fallbackAngle);
            }

            const pushX = ux * minSepX * overlapRatio * 0.56;
            const pushY = uy * minSepY * overlapRatio * 0.56;

            const weightA = a.level < b.level ? 0.32 : a.level > b.level ? 0.68 : 0.5;
            const weightB = 1 - weightA;

            const moveAx = -pushX * weightA * 2;
            const moveAy = -pushY * weightA * 2;
            const moveBx = pushX * weightB * 2;
            const moveBy = pushY * weightB * 2;

            a.position.x += moveAx;
            a.position.y += moveAy;
            b.position.x += moveBx;
            b.position.y += moveBy;

            if (a.expanded && a.children && a.children.length > 0 && b.parentId !== a.id) {
              shiftSubtree(a, moveAx * 0.45, moveAy * 0.45);
            }
            if (b.expanded && b.children && b.children.length > 0 && a.parentId !== b.id) {
              shiftSubtree(b, moveBx * 0.45, moveBy * 0.45);
            }
          }
        }
      }

      if (maxOverlap < 0.5) break;
    }

    for (let i = 0; i < n; i++) {
      visibleNodes[i].position.x = Math.round(visibleNodes[i].position.x);
      visibleNodes[i].position.y = Math.round(visibleNodes[i].position.y);
    }
  }

  function shiftSubtree(parentNode, dx, dy) {
    if (!parentNode.expanded || !parentNode.children) return;
    for (const child of parentNode.children) {
      child.position.x += dx;
      child.position.y += dy;
      if (child.expanded && child.children && child.children.length > 0) {
        shiftSubtree(child, dx, dy);
      }
    }
  }

  function getVisibleNodesAndLinks() {
    const visibleNodes = [];
    const links = [];

    function traverse(nodes, parentPos) {
      for (const node of nodes) {
        visibleNodes.push(node);
        links.push({
          id: `link-${node.parentId}-${node.id}`,
          from: parentPos,
          to: node.position,
          level: node.level,
          targetNode: node
        });
        if (node.expanded && node.children && node.children.length > 0) {
          traverse(node.children, node.position);
        }
      }
    }

    traverse(appState.nodes, { x: 0, y: 0 });
    return { visibleNodes, links };
  }

  // =========================================================
  // RENDER ENGINE: ORGANIC SVG BRANCHES & LEAVES + NODES
  // =========================================================
  const tendrilsLayer = document.getElementById('branch-tendrils-layer');
  const glowLayer = document.getElementById('branch-glow-layer');
  const mainLayer = document.getElementById('branch-main-layer');
  const leavesLayer = document.getElementById('branch-leaves-layer');
  const nodesLayer = document.getElementById('nodes-layer');

  function renderCanvas(skipAutoLayout = false) {
    recalculateTreeStatuses(appState.nodes);
    if (!skipAutoLayout) {
      computeDynamicTreeLayout();
    }
    const { visibleNodes, links } = getVisibleNodesAndLinks();

    renderBranchesSVG(links);
    renderNodesDOM(visibleNodes);
    renderRootCenterText();
    renderMotto();
  }

  function renderBranchesSVG(links) {
    tendrilsLayer.innerHTML = '';
    glowLayer.innerHTML = '';
    mainLayer.innerHTML = '';
    leavesLayer.innerHTML = '';

    const svgNS = 'http://www.w3.org/2000/svg';

    links.forEach((link, idx) => {
      const { from, to, level, targetNode } = link;
      const dx = to.x - from.x;
      const dy = to.y - from.y;
      const dist = Math.hypot(dx, dy);
      if (dist < 1) return;

      let sx = from.x;
      let sy = from.y;
      if (level === 1) {
        const angle = Math.atan2(dy, dx);
        sx = Math.cos(angle) * 102;
        sy = Math.sin(angle) * 102;
      }

      const perpX = -(to.y - sy) * 0.14 * (idx % 2 === 0 ? 1 : -1);
      const perpY = (to.x - sx) * 0.12;

      const cp1x = sx + (to.x - sx) * 0.34 + perpX * 0.45;
      const cp1y = sy + (to.y - sy) * 0.18 + perpY * 0.55;
      const cp2x = sx + (to.x - sx) * 0.68 - perpX * 0.32;
      const cp2y = sy + (to.y - sy) * 0.84 - perpY * 0.32;

      const pathData = `M ${sx.toFixed(1)} ${sy.toFixed(1)} C ${cp1x.toFixed(1)} ${cp1y.toFixed(1)}, ${cp2x.toFixed(1)} ${cp2y.toFixed(1)}, ${to.x.toFixed(1)} ${to.y.toFixed(1)}`;

      const strokeGrad =
        level === 1
          ? to.x < 0
            ? 'url(#grad-branch-left)'
            : 'url(#grad-branch-right)'
          : 'url(#grad-branch-sub)';

      const strokeWidth = level === 1 ? 3.2 : level === 2 ? 2.4 : level === 3 ? 1.9 : 1.5;

      const glowPath = document.createElementNS(svgNS, 'path');
      glowPath.setAttribute('d', pathData);
      glowPath.setAttribute('class', 'branch-path-glow');
      glowPath.setAttribute('stroke', strokeGrad);
      glowPath.setAttribute('stroke-width', String(strokeWidth * 2.4));
      glowLayer.appendChild(glowPath);

      const mainPath = document.createElementNS(svgNS, 'path');
      mainPath.setAttribute('d', pathData);
      mainPath.setAttribute('class', 'branch-path-main');
      mainPath.setAttribute('stroke', strokeGrad);
      mainPath.setAttribute('stroke-width', String(strokeWidth));

      if (newlyAnimatedNodeIds.has(targetNode.id)) {
        const approxLen = Math.round(dist * 1.25);
        mainPath.style.strokeDasharray = `${approxLen}`;
        mainPath.style.strokeDashoffset = `${approxLen}`;
        requestAnimationFrame(() => {
          mainPath.style.strokeDashoffset = '0';
        });
      }
      mainLayer.appendChild(mainPath);

      const tX = 0.52 * sx + 0.48 * to.x + perpX * 0.2;
      const tY = 0.52 * sy + 0.48 * to.y + perpY * 0.2;
      const branchAngle = Math.atan2(to.y - sy, to.x - sx);
      const sideSign = idx % 2 === 0 ? 1 : -1;
      const tendrilEndAngle = branchAngle + sideSign * 0.68;
      const tendrilLen = level === 1 ? 32 : 22;
      const tx2 = tX + Math.cos(tendrilEndAngle) * tendrilLen;
      const ty2 = tY + Math.sin(tendrilEndAngle) * tendrilLen;
      const tendrilCtrlX = tX + Math.cos(branchAngle) * (tendrilLen * 0.55);
      const tendrilCtrlY = tY + Math.sin(branchAngle) * (tendrilLen * 0.55);

      const tendrilPath = document.createElementNS(svgNS, 'path');
      tendrilPath.setAttribute(
        'd',
        `M ${tX.toFixed(1)} ${tY.toFixed(1)} Q ${tendrilCtrlX.toFixed(1)} ${tendrilCtrlY.toFixed(1)}, ${tx2.toFixed(1)} ${ty2.toFixed(1)}`
      );
      tendrilPath.setAttribute('class', 'branch-tendril');
      tendrilsLayer.appendChild(tendrilPath);

      const leafPositions = [
        { t: 0.38, angleOffset: -36 * sideSign, scale: level === 1 ? 0.92 : 0.76 },
        { t: 0.66, angleOffset: 32 * sideSign, scale: level === 1 ? 0.8 : 0.66 }
      ];

      leafPositions.forEach((lp) => {
        const mt = 1 - lp.t;
        const lx =
          mt * mt * mt * sx +
          3 * mt * mt * lp.t * cp1x +
          3 * mt * lp.t * lp.t * cp2x +
          lp.t * lp.t * lp.t * to.x;
        const ly =
          mt * mt * mt * sy +
          3 * mt * mt * lp.t * cp1y +
          3 * mt * lp.t * lp.t * cp2y +
          lp.t * lp.t * lp.t * to.y;
        const deg = (branchAngle * 180) / Math.PI + lp.angleOffset;
        const leaf = document.createElementNS(svgNS, 'path');
        leaf.setAttribute('d', 'M 0 0 C 5 -6, 13 -6, 17 0 C 13 6, 5 6, 0 0 Z');
        leaf.setAttribute('class', 'branch-leaf');
        leaf.setAttribute(
          'transform',
          `translate(${lx.toFixed(1)}, ${ly.toFixed(1)}) rotate(${deg.toFixed(1)}) scale(${lp.scale})`
        );
        leavesLayer.appendChild(leaf);
      });
    });
  }

  function renderNodesDOM(visibleNodes) {
    nodesLayer.innerHTML = '';

    visibleNodes.forEach((node, idx) => {
      const isParent = node.children && node.children.length > 0;
      const wrapper = document.createElement('div');
      wrapper.className = `task-node-wrapper level-${node.level} status-${node.status}${node.id === selectedNodeId ? ' is-selected' : ''}`;
      wrapper.dataset.nodeId = node.id;
      wrapper.style.left = `${node.position.x}px`;
      wrapper.style.top = `${node.position.y}px`;

      if (newlyAnimatedNodeIds.has(node.id)) {
        wrapper.style.animationDelay = '0.05s';
      }

      const orb = document.createElement('div');
      orb.className = 'task-node-orb';

      const indexEl = document.createElement('div');
      indexEl.className = 'node-index';
      indexEl.textContent = node.code || String(idx + 1).padStart(2, '0');
      orb.appendChild(indexEl);

      const titleEl = document.createElement('div');
      titleEl.className = 'node-title';
      titleEl.textContent = node.text;
      titleEl.title = '点击编辑任务名称';
      titleEl.addEventListener('click', (e) => {
        e.stopPropagation();
        startInlineEditNode(node, titleEl);
      });
      orb.appendChild(titleEl);

      const statusRow = document.createElement('div');
      statusRow.className = 'node-status-row';
      statusRow.innerHTML = buildNodeStatusHTML(node, isParent);
      statusRow.title = isParent
        ? '父节点进度由子任务自动汇总（点击展开/收起子任务）'
        : '点击切换四态角色举牌状态';
      statusRow.addEventListener('click', (e) => {
        e.stopPropagation();
        if (isParent) {
          toggleNodeExpand(node.id);
          showToast(`父节点「${node.text}」状态由 ${node.progress.current}/${node.progress.total} 个子任务自动计算`);
        } else {
          openStatusPopover(node.id, e.clientX, e.clientY);
        }
      });
      orb.appendChild(statusRow);

      if (isParent && node.hasStuckDescendant) {
        const stuckCorner = document.createElement('div');
        stuckCorner.className = 'parent-stuck-corner';
        stuckCorner.textContent = '⚡ 含受阻项';
        stuckCorner.title = '其下有子任务处于「卡住了…」状态';
        orb.appendChild(stuckCorner);
      }

      if (isParent) {
        const branchToggle = document.createElement('button');
        branchToggle.className = 'node-branch-toggle';
        branchToggle.textContent = `${node.expanded ? '▾' : '▸'} ${node.children.length}`;
        branchToggle.title = node.expanded ? '点击收起子分支' : '点击展开下一层子分支';
        branchToggle.addEventListener('click', (e) => {
          e.stopPropagation();
          toggleNodeExpand(node.id);
        });
        orb.appendChild(branchToggle);
      }

      const charBadge = document.createElement('div');
      const offsetClass =
        node.position.x < -120 ? 'pos-left' : node.position.x > 120 ? 'pos-right' : '';
      charBadge.className = `node-char-badge ${offsetClass}`;
      charBadge.title = isParent
        ? `当前汇总状态：${STATUS_LABELS[node.status]} (${node.progress.current}/${node.progress.total})`
        : `当前状态：${STATUS_LABELS[node.status]}（点击切换四态角色）`;

      const charImg = document.createElement('img');
      charImg.className = 'node-char-img';
      charImg.src = CHAR_SPRITES[node.status] || CHAR_SPRITES.empty;
      charImg.alt = STATUS_LABELS[node.status];
      charBadge.appendChild(charImg);

      charBadge.addEventListener('click', (e) => {
        e.stopPropagation();
        if (isParent) {
          showToast(`父节点状态由子任务完成情况自动计算（${node.progress.current}/${node.progress.total}）`);
          if (!node.expanded) toggleNodeExpand(node.id);
        } else {
          openStatusPopover(node.id, e.clientX, e.clientY);
        }
      });

      const hoverActions = document.createElement('div');
      hoverActions.className = 'node-hover-actions';

      const addBtn = document.createElement('button');
      const isMaxLevel = node.level >= MAX_LEVEL;
      addBtn.className = `node-micro-btn ${isMaxLevel ? 'disabled' : ''}`;
      addBtn.textContent = '＋';
      addBtn.title = isMaxLevel
        ? '已达到最大拆解层级（最多 4 层）'
        : `拆解第 ${node.level + 1} 层子任务`;
      addBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (isMaxLevel) {
          showToast('已达到最大拆解层级（最多 4 层），不可继续新增子节点');
          return;
        }
        openAddChildModal(node.id);
      });

      const delBtn = document.createElement('button');
      delBtn.className = 'node-micro-btn delete-btn';
      delBtn.textContent = '×';
      delBtn.title = '删除此节点';
      delBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        requestDeleteNode(node.id);
      });

      hoverActions.appendChild(addBtn);
      hoverActions.appendChild(delBtn);

      setupNodeInteractions(wrapper, orb, node);

      wrapper.appendChild(orb);
      wrapper.appendChild(charBadge);
      wrapper.appendChild(hoverActions);
      nodesLayer.appendChild(wrapper);
    });

    newlyAnimatedNodeIds.clear();
  }

  function buildNodeStatusHTML(node, isParent) {
    if (node.status === 'done') {
      return `<span class="status-done-text"><span class="status-check-icon">✓</span> 已完成</span>`;
    }
    if (node.status === 'stuck' && !isParent) {
      return `<span class="status-stuck-text">☁ 卡住了…</span>`;
    }

    const cur = node.progress ? node.progress.current : 0;
    const tot = node.progress ? node.progress.total : 1;

    if (node.status === 'in_progress') {
      const ratio = tot > 0 ? Math.max(0.25, cur / tot) : 0.5;
      const circumference = 2 * Math.PI * 5.2;
      const dash = (circumference * ratio).toFixed(1);
      return `
        <svg class="progress-ring-svg" viewBox="0 0 14 14">
          <circle cx="7" cy="7" r="5.2" fill="none" stroke="rgba(130, 175, 215, 0.35)" stroke-width="1.8" />
          <circle cx="7" cy="7" r="5.2" fill="none" stroke="#45cbbf" stroke-width="2"
            stroke-linecap="round"
            stroke-dasharray="${dash} ${circumference.toFixed(1)}"
            transform="rotate(-90 7 7)" />
        </svg>
        <span>${isParent ? `${cur} / ${tot}` : `${cur || 1} / ${tot}`}</span>
      `;
    }

    return `
      <svg class="progress-ring-svg" viewBox="0 0 14 14">
        <circle cx="7" cy="7" r="5.2" fill="none" stroke="rgba(78, 112, 162, 0.65)" stroke-width="1.3" />
      </svg>
      <span>0 / ${tot}</span>
    `;
  }

  // =========================================================
  // NODE DRAG / CLICK / CONTEXT MENU INTERACTIONS
  // =========================================================
  function setupNodeInteractions(wrapper, orb, node) {
    let isDraggingNode = false;
    let movedDistance = 0;
    let startClientX = 0;
    let startClientY = 0;
    let origX = 0;
    let origY = 0;
    let longPressTimer = null;

    orb.addEventListener('pointerdown', (e) => {
      if (e.button === 2) return;
      if (e.target.closest('button') || e.target.closest('input')) return;
      e.stopPropagation();

      if (selectedNodeId !== node.id) {
        selectedNodeId = node.id;
        nodesLayer.querySelectorAll('.task-node-wrapper.is-selected').forEach((el) => el.classList.remove('is-selected'));
        wrapper.classList.add('is-selected');
      }

      isDraggingNode = true;
      movedDistance = 0;
      startClientX = e.clientX;
      startClientY = e.clientY;
      origX = node.position.x;
      origY = node.position.y;
      try { orb.setPointerCapture(e.pointerId); } catch (_) {}

      longPressTimer = setTimeout(() => {
        if (movedDistance < 6) {
          isDraggingNode = false;
          openContextMenu(node.id, e.clientX, e.clientY);
        }
      }, 550);
    });

    let dragRafPending = false;
    orb.addEventListener('pointermove', (e) => {
      if (!isDraggingNode) return;
      const dx = (e.clientX - startClientX) / camera.scale;
      const dy = (e.clientY - startClientY) / camera.scale;
      movedDistance = Math.hypot(dx, dy);

      if (movedDistance > 6) {
        clearTimeout(longPressTimer);
        node._userDragged = true;
        node.position.x = Math.round(origX + dx);
        node.position.y = Math.round(origY + dy);
        wrapper.style.left = `${node.position.x}px`;
        wrapper.style.top = `${node.position.y}px`;
        if (!dragRafPending) {
          dragRafPending = true;
          requestAnimationFrame(() => {
            dragRafPending = false;
            const { links } = getVisibleNodesAndLinks();
            renderBranchesSVG(links);
          });
        }
      }
    });

    orb.addEventListener('pointerup', (e) => {
      clearTimeout(longPressTimer);
      if (!isDraggingNode) return;
      isDraggingNode = false;

      if (movedDistance > 6) {
        node.updatedAt = Date.now();
        saveState();
      } else {
        if (node.children && node.children.length > 0) {
          toggleNodeExpand(node.id);
        } else {
          openStatusPopover(node.id, e.clientX, e.clientY);
        }
      }
    });

    wrapper.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      e.stopPropagation();
      openContextMenu(node.id, e.clientX, e.clientY);
    });
  }

  function toggleNodeExpand(nodeId) {
    const found = findNodeById(nodeId);
    if (!found) return;
    const { node } = found;
    if (!node.children || node.children.length === 0) {
      showToast('该节点暂无子分支，可点击「＋」拆解下一层任务');
      return;
    }
    node.expanded = !node.expanded;
    if (node.expanded) {
      node.children.forEach((c) => newlyAnimatedNodeIds.add(c.id));
    }
    saveState();
    renderCanvas();
  }

  function startInlineEditNode(node, titleEl) {
    const input = document.createElement('input');
    input.type = 'text';
    input.className = 'node-inline-input';
    input.value = node.text;
    input.maxLength = 28;

    titleEl.replaceWith(input);
    input.focus();
    input.select();

    const finishEdit = () => {
      const val = input.value.trim();
      if (val) {
        node.text = val;
        node.updatedAt = Date.now();
        saveState();
      }
      renderCanvas(true);
      if (currentView === 'list') renderTaskListView();
      if (currentView === 'memory') renderMemoryView();
    };

    input.addEventListener('keydown', (e) => {
      e.stopPropagation();
      if (e.key === 'Enter') {
        finishEdit();
      } else if (e.key === 'Escape') {
        renderCanvas(true);
      }
    });

    input.addEventListener('blur', finishEdit);
    input.addEventListener('click', (e) => e.stopPropagation());
  }

  // =========================================================
  // CENTER CIRCLE (ROOT NODE) & MOTTO INTERACTIONS
  // =========================================================
  const rootInputZone = document.getElementById('root-input-zone');
  const rootCursorDisplay = document.getElementById('root-cursor-display');
  const rootSavedText = document.getElementById('root-saved-text');
  const rootTextarea = document.getElementById('root-textarea');
  const btnSproutSave = document.getElementById('btn-sprout-save');
  const btnRootAddChild = document.getElementById('btn-root-add-child');

  function renderRootCenterText() {
    rootSavedText.textContent = appState.rootText || '';
    if (appState.rootText) {
      rootCursorDisplay.classList.add('root-Cursor-centered');
    } else {
      rootCursorDisplay.classList.remove('root-Cursor-centered');
    }
  }

  function enterRootEditMode() {
    rootCursorDisplay.classList.add('hidden');
    rootTextarea.classList.remove('hidden');
    rootTextarea.value = appState.rootText || '';
    rootTextarea.focus();
  }

  function saveRootThought(showFeedback = true) {
    if (!rootTextarea.classList.contains('hidden')) {
      appState.rootText = rootTextarea.value.trim();
      rootTextarea.classList.add('hidden');
      rootCursorDisplay.classList.remove('hidden');
    }
    saveState();
    renderRootCenterText();
    renderTaskListView();
    if (showFeedback) {
      triggerCelebration(0, -15, 16);
      showToast(
        appState.rootText
          ? `核心念头「${appState.rootText}」已扎根发芽`
          : '中心圆已保存为空白待输入状态'
      );
    }
  }

  rootInputZone.addEventListener('click', (e) => {
    e.stopPropagation();
    enterRootEditMode();
  });

  rootTextarea.addEventListener('keydown', (e) => {
    e.stopPropagation();
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      saveRootThought(true);
    } else if (e.key === 'Escape') {
      rootTextarea.classList.add('hidden');
      rootCursorDisplay.classList.remove('hidden');
    }
  });

  btnSproutSave.addEventListener('click', (e) => {
    e.stopPropagation();
    if (rootTextarea.classList.contains('hidden') && !appState.rootText) {
      enterRootEditMode();
      showToast('请输入你的核心念头，再点击「开始发芽」保存');
      return;
    }
    saveRootThought(true);
  });

  btnRootAddChild.addEventListener('click', (e) => {
    e.stopPropagation();
    openAddChildModal('root');
  });

  const mottoBanner = document.getElementById('motto-banner');
  const mottoText = document.getElementById('motto-text');
  const mottoInput = document.getElementById('motto-input');

  function renderMotto() {
    mottoText.textContent = appState.motto || '问鼎巅峰之路';
  }

  mottoBanner.addEventListener('dblclick', () => {
    mottoText.classList.add('hidden');
    mottoInput.classList.remove('hidden');
    mottoInput.value = appState.motto || '问鼎巅峰之路';
    mottoInput.focus();
    mottoInput.select();
  });

  function saveMottoEdit() {
    if (mottoInput.classList.contains('hidden')) return;
    const val = mottoInput.value.trim();
    if (val) appState.motto = val;
    mottoInput.classList.add('hidden');
    mottoText.classList.remove('hidden');
    saveState();
    renderMotto();
  }

  mottoInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') saveMottoEdit();
    if (e.key === 'Escape') {
      mottoInput.classList.add('hidden');
      mottoText.classList.remove('hidden');
    }
  });
  mottoInput.addEventListener('blur', saveMottoEdit);

  // =========================================================
  // STATUS POPOVER, ADD MODAL, DELETE/END CONFIRM & CONTEXT MENU
  // =========================================================
  const statusPopover = document.getElementById('status-popover');
  const nodeContextMenu = document.getElementById('node-context-menu');
  const nodeFormModal = document.getElementById('node-form-modal');
  const modalLevelBadge = document.getElementById('modal-level-badge');
  const modalTitle = document.getElementById('modal-title');
  const modalSubtitle = document.getElementById('modal-subtitle');
  const modalNodeInput = document.getElementById('modal-node-input');
  const deleteConfirmModal = document.getElementById('delete-confirm-modal');
  const deleteModalDesc = document.getElementById('delete-modal-desc');
  const endConfirmModal = document.getElementById('end-confirm-modal');
  const endModalDesc = document.getElementById('end-modal-desc');
  const deleteMemoryConfirmModal = document.getElementById('delete-memory-confirm-modal');
  const deleteMemoryModalDesc = document.getElementById('delete-memory-modal-desc');

  function closeAllFloatingMenus() {
    statusPopover.classList.add('hidden');
    nodeContextMenu.classList.add('hidden');
    activePopoverNodeId = null;
    activeContextNodeId = null;
  }

  window.addEventListener('click', () => {
    closeAllFloatingMenus();
  });

  function openStatusPopover(nodeId, clientX, clientY) {
    closeAllFloatingMenus();
    const found = findNodeById(nodeId);
    if (!found) return;
    const { node } = found;

    if (node.children && node.children.length > 0) {
      showToast('父节点状态由子任务自动汇总计算，请切换具体叶子节点状态');
      return;
    }

    activePopoverNodeId = nodeId;
    statusPopover.querySelectorAll('.char-state-option').forEach((btn) => {
      btn.classList.toggle('active', btn.dataset.status === node.status);
    });

    statusPopover.classList.remove('hidden');
    const popW = 296;
    const popH = 150;
    const left = Math.min(window.innerWidth - popW - 16, Math.max(16, clientX - popW / 2));
    const top = Math.min(window.innerHeight - popH - 16, Math.max(64, clientY + 14));
    statusPopover.style.left = `${left}px`;
    statusPopover.style.top = `${top}px`;
  }

  statusPopover.addEventListener('click', (e) => {
    e.stopPropagation();
    const btn = e.target.closest('.char-state-option');
    if (!btn || !activePopoverNodeId) return;
    const newStatus = btn.dataset.status;
    setLeafNodeStatus(activePopoverNodeId, newStatus);
    closeAllFloatingMenus();
  });

  function setLeafNodeStatus(nodeId, newStatus) {
    const found = findNodeById(nodeId);
    if (!found) return;
    const { node, parent } = found;
    if (node.children && node.children.length > 0) {
      showToast('父节点状态由子任务自动计算，不可手动设置');
      return;
    }

    const oldStatus = node.status;
    node.status = newStatus;
    node.updatedAt = Date.now();
    node.completedAt = newStatus === 'done' ? (node.completedAt || Date.now()) : null;

    const parentWasDone = parent ? parent.status === 'done' : false;
    saveState();

    if (newStatus === 'done' && oldStatus !== 'done') {
      triggerCelebration(node.position.x, node.position.y, 24);
      if (parent && parent.status === 'done' && !parentWasDone) {
        setTimeout(() => {
          triggerCelebration(parent.position.x, parent.position.y, 28);
          showToast(`🎉 分支「${parent.text}」下所有子任务已全部完成！`);
        }, 320);
      } else {
        showToast(`🌸 「${node.text}」已完成并写入回忆记录！`);
      }
    } else {
      showToast(`已将「${node.text}」状态更新为：${STATUS_LABELS[newStatus]}`);
    }

    renderCanvas(true);
    if (currentView === 'list') renderTaskListView();
    if (currentView === 'memory') renderMemoryView();
  }

  function openContextMenu(nodeId, clientX, clientY) {
    closeAllFloatingMenus();
    const found = findNodeById(nodeId);
    if (!found) return;
    const { node } = found;
    activeContextNodeId = nodeId;

    const addChildBtn = document.getElementById('ctx-add-child');
    const toggleExpandBtn = document.getElementById('ctx-toggle-expand');
    const changeStatusBtn = document.getElementById('ctx-change-status');
    const endNodeBtn = document.getElementById('ctx-end-node');

    if (node.level >= MAX_LEVEL) {
      addChildBtn.textContent = '🚫 已达第 4 层最大拆解限制';
      addChildBtn.style.opacity = '0.5';
    } else {
      addChildBtn.textContent = `🌱 新增第 ${node.level + 1} 层子任务`;
      addChildBtn.style.opacity = '1';
    }

    toggleExpandBtn.style.display =
      node.children && node.children.length > 0 ? 'flex' : 'none';
    changeStatusBtn.style.display =
      !node.children || node.children.length === 0 ? 'flex' : 'none';
    if (endNodeBtn) {
      endNodeBtn.style.display = node.status === 'done' ? 'flex' : 'none';
    }

    nodeContextMenu.classList.remove('hidden');
    const left = Math.min(window.innerWidth - 190, Math.max(12, clientX));
    const top = Math.min(window.innerHeight - 245, Math.max(60, clientY));
    nodeContextMenu.style.left = `${left}px`;
    nodeContextMenu.style.top = `${top}px`;
  }

  document.getElementById('ctx-add-child').addEventListener('click', (e) => {
    e.stopPropagation();
    const id = activeContextNodeId;
    closeAllFloatingMenus();
    if (!id) return;
    const found = findNodeById(id);
    if (found && found.node.level >= MAX_LEVEL) {
      showToast('已达到最大拆解层级（最多 4 层）');
      return;
    }
    openAddChildModal(id);
  });

  document.getElementById('ctx-toggle-expand').addEventListener('click', (e) => {
    e.stopPropagation();
    const id = activeContextNodeId;
    closeAllFloatingMenus();
    if (id) toggleNodeExpand(id);
  });

  document.getElementById('ctx-edit-text').addEventListener('click', (e) => {
    e.stopPropagation();
    const id = activeContextNodeId;
    closeAllFloatingMenus();
    if (!id) return;
    const wrapper = nodesLayer.querySelector(`[data-node-id="${id}"]`);
    if (wrapper) {
      const titleEl = wrapper.querySelector('.node-title');
      const found = findNodeById(id);
      if (titleEl && found) startInlineEditNode(found.node, titleEl);
    }
  });

  document.getElementById('ctx-change-status').addEventListener('click', (e) => {
    e.stopPropagation();
    const id = activeContextNodeId;
    const rect = nodeContextMenu.getBoundingClientRect();
    closeAllFloatingMenus();
    if (id) openStatusPopover(id, rect.left, rect.top);
  });

  document.getElementById('ctx-end-node').addEventListener('click', (e) => {
    e.stopPropagation();
    const id = activeContextNodeId;
    closeAllFloatingMenus();
    if (id) requestEndNode(id);
  });

  document.getElementById('ctx-delete-node').addEventListener('click', (e) => {
    e.stopPropagation();
    const id = activeContextNodeId;
    closeAllFloatingMenus();
    if (id) requestDeleteNode(id);
  });

  function openAddChildModal(parentId) {
    closeAllFloatingMenus();
    pendingAddParentId = parentId;

    if (parentId === 'root') {
      modalLevelBadge.textContent = '第 1 层 · 主干任务';
      modalTitle.textContent = '从中心圆生长新分支';
      modalSubtitle.textContent = '输入要开启的一级核心任务，随后可继续向第 2-4 层细化拆解';
    } else {
      const found = findNodeById(parentId);
      if (!found) return;
      if (found.node.level >= MAX_LEVEL) {
        showToast('已达到最大拆解层级（最多 4 层）');
        return;
      }
      const nextLv = found.node.level + 1;
      modalLevelBadge.textContent = `第 ${nextLv} 层 · 拆解子任务`;
      modalTitle.textContent = `为「${found.node.text}」新增子分支`;
      modalSubtitle.textContent =
        nextLv === MAX_LEVEL
          ? '当前为第 4 层（最小可执行动作层），此层节点将作为最终执行叶节点'
          : '用第一性原理将任务拆解为更小、更易启动的具体动作';
    }

    modalNodeInput.value = '';
    nodeFormModal.classList.remove('hidden');
    setTimeout(() => modalNodeInput.focus(), 40);
  }

  function confirmAddChildNode() {
    const text = modalNodeInput.value.trim();
    if (!text) {
      showToast('请输入任务内容');
      modalNodeInput.focus();
      return;
    }

    const now = Date.now();
    let createdNode = null;

    if (pendingAddParentId === 'root') {
      const leftCount = appState.nodes.filter((n) => n.side === 'left').length;
      const rightCount = appState.nodes.filter((n) => n.side !== 'left').length;
      const side = leftCount <= rightCount ? 'left' : 'right';
      createdNode = {
        id: `n-${now}`,
        code: String(appState.nodes.length + 1).padStart(2, '0'),
        text,
        status: 'empty',
        level: 1,
        parentId: 'root',
        side,
        orderIndex: appState.nodes.length,
        position: { x: side === 'left' ? -360 : 360, y: 0 },
        expanded: true,
        createdAt: now,
        updatedAt: now,
        children: []
      };
      appState.nodes.push(createdNode);
    } else {
      const found = findNodeById(pendingAddParentId);
      if (!found) return;
      const parentNode = found.node;
      if (parentNode.level >= MAX_LEVEL) {
        showToast('已达到最大拆解层级（最多 4 层）');
        nodeFormModal.classList.add('hidden');
        return;
      }
      parentNode.expanded = true;
      if (!parentNode.children) parentNode.children = [];
      createdNode = {
        id: `n-${now}`,
        code: `${parentNode.code}.${parentNode.children.length + 1}`,
        text,
        status: 'empty',
        level: parentNode.level + 1,
        parentId: parentNode.id,
        position: { x: parentNode.position.x, y: parentNode.position.y },
        expanded: true,
        createdAt: now,
        updatedAt: now,
        children: []
      };
      parentNode.children.push(createdNode);
    }

    nodeFormModal.classList.add('hidden');
    newlyAnimatedNodeIds.add(createdNode.id);
    renderCanvas(false);
    saveState();
    if (currentView === 'list') renderTaskListView();
    if (currentView === 'memory') renderMemoryView();

    if (currentView === 'canvas') {
      smoothPanToNode(createdNode);
    }
    showToast(`🌱 新芽「${createdNode.text}」已生长（第 ${createdNode.level} 层）`);
  }

  document.getElementById('btn-modal-cancel').addEventListener('click', () => {
    nodeFormModal.classList.add('hidden');
  });

  document.getElementById('btn-modal-confirm').addEventListener('click', confirmAddChildNode);

  modalNodeInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') confirmAddChildNode();
    if (e.key === 'Escape') nodeFormModal.classList.add('hidden');
  });

  // Delete Node Confirmation (unified for both parent and leaf nodes, always stating memories are kept)
  function requestDeleteNode(nodeId) {
    const found = findNodeById(nodeId);
    if (!found) return;
    const { node } = found;
    const descCount = countDescendants(node);
    pendingDeleteNodeId = nodeId;

    if (descCount > 0) {
      deleteModalDesc.textContent = `节点「${node.text}」下包含子分支，删除时将同时删除其下 ${descCount} 个子任务。已完成的回忆记录会保留，不会被删除。是否确认删除？`;
    } else {
      deleteModalDesc.textContent = `确认从画布和任务树中删除节点「${node.text}」吗？若该节点曾完成过，已写入的回忆记录会保留，不会被删除。`;
    }
    deleteConfirmModal.classList.remove('hidden');
  }

  function executeDeleteNode(nodeId) {
    const found = findNodeById(nodeId);
    if (!found) return;
    const { node, list, index } = found;
    const deletedName = node.text;
    list.splice(index, 1);
    deleteConfirmModal.classList.add('hidden');
    pendingDeleteNodeId = null;
    renderCanvas(false);
    saveState();
    if (currentView === 'list') renderTaskListView();
    if (currentView === 'memory') renderMemoryView();
    showToast(`已移除节点「${deletedName}」（已有回忆记录已保留）`);
  }

  document.getElementById('btn-delete-cancel').addEventListener('click', () => {
    deleteConfirmModal.classList.add('hidden');
    pendingDeleteNodeId = null;
  });

  document.getElementById('btn-delete-confirm').addEventListener('click', () => {
    if (pendingDeleteNodeId) executeDeleteNode(pendingDeleteNodeId);
  });

  // =========================================================
  // END NODE ("结束此节点") WORKFLOW & REPLANTING
  // =========================================================
  function requestEndNode(nodeId) {
    const found = findNodeById(nodeId);
    if (!found) return;
    const { node } = found;
    if (node.status !== 'done') {
      showToast('只有状态为「已完成」的节点才可以结束归档');
      return;
    }

    const descCount = countDescendants(node);
    pendingEndNodeId = nodeId;
    if (descCount > 0) {
      endModalDesc.textContent = `确认结束「${node.text}」及其下 ${descCount} 个子任务吗？结束后整棵子树将从画布与树中移走，并在回忆记录中标为「已结束」，随时可重新种回。`;
    } else {
      endModalDesc.textContent = `确认结束已完成节点「${node.text}」吗？结束后将从画布与任务树中移走，并在回忆记录中标记为「已结束」，随时可重新种回。`;
    }
    endConfirmModal.classList.remove('hidden');
  }

  function executeEndNode(nodeId) {
    const found = findNodeById(nodeId);
    if (!found) return;
    const { node, parent, list, index } = found;
    if (node.status !== 'done') return;

    const now = Date.now();
    const pathNames = findNodePathNames(node.id) || [];
    const pathStr = pathNames.length > 0 ? pathNames.join(' / ') : '第 1 层主干任务';

    // Sync any done records before removing
    syncDoneSnapshotsToMemories(appState);

    const snapshot = deepClone(node);
    let mem = appState.memories.find((m) => m.id === node.id);
    if (!mem) {
      mem = {
        id: node.id,
        text: node.text,
        path: pathStr,
        level: node.level,
        parentId: node.parentId || 'root',
        completedAt: node.completedAt || node.updatedAt || now,
        ended: true,
        endedAt: now,
        archivedWithParentId: null,
        nodeSnapshot: snapshot
      };
      appState.memories.push(mem);
    } else {
      mem.text = node.text;
      mem.path = pathStr;
      mem.level = node.level;
      mem.parentId = node.parentId || 'root';
      mem.ended = true;
      mem.endedAt = now;
      mem.archivedWithParentId = null;
      mem.nodeSnapshot = snapshot;
    }

    // Mark any descendant records already in memories as ended & grouped under this parent snapshot
    (function markDescendantsEnded(children) {
      if (!children) return;
      for (const c of children) {
        const childMem = appState.memories.find((m) => m.id === c.id);
        if (childMem) {
          childMem.ended = true;
          childMem.endedAt = now;
          childMem.archivedWithParentId = node.id;
          childMem.nodeSnapshot = deepClone(c);
        }
        if (c.children && c.children.length > 0) {
          markDescendantsEnded(c.children);
        }
      }
    })(node.children);

    // Remove node & subtree from active tree
    list.splice(index, 1);

    // If parent had children and ALL of them have now been ended, parent stays 'done' (cannot regress)
    if (parent && parent.children.length === 0) {
      parent.status = 'done';
      parent.completedAt = parent.completedAt || now;
      parent.updatedAt = now;
    }

    endConfirmModal.classList.add('hidden');
    pendingEndNodeId = null;
    renderCanvas(false);
    saveState();
    if (currentView === 'list') renderTaskListView();
    if (currentView === 'memory') renderMemoryView();
    showToast(`🍂 「${node.text}」已结束并归档至回忆记录`);
  }

  document.getElementById('btn-end-cancel').addEventListener('click', () => {
    endConfirmModal.classList.add('hidden');
    pendingEndNodeId = null;
  });

  document.getElementById('btn-end-confirm').addEventListener('click', () => {
    if (pendingEndNodeId) executeEndNode(pendingEndNodeId);
  });

  function replantMemory(memoryId) {
    const mem = appState.memories.find((m) => m.id === memoryId);
    if (!mem || !mem.ended) return;

    const restored = mem.nodeSnapshot
      ? deepClone(mem.nodeSnapshot)
      : {
          id: mem.id,
          code: '01',
          text: mem.text,
          status: 'done',
          level: 1,
          parentId: 'root',
          position: { x: 0, y: 0 },
          expanded: false,
          createdAt: mem.completedAt || Date.now(),
          updatedAt: Date.now(),
          completedAt: mem.completedAt || Date.now(),
          children: []
        };

    // Guard against duplicate ID if already present on tree
    if (findNodeById(restored.id)) {
      restored.id = `n-${Date.now()}`;
      mem.id = restored.id;
    }

    // Ensure restored node retains done status & clears user-dragged lock for fresh collision-free layout
    restored.status = 'done';
    restored.completedAt = mem.completedAt || restored.completedAt || Date.now();
    (function resetLayoutFlags(n) {
      n._userDragged = false;
      n.status = 'done';
      if (n.children && n.children.length > 0) {
        n.children.forEach(resetLayoutFlags);
      }
    })(restored);

    let targetParentFound = null;
    if (mem.parentId && mem.parentId !== 'root') {
      const foundParent = findNodeById(mem.parentId);
      if (foundParent && foundParent.node.level < MAX_LEVEL) {
        targetParentFound = foundParent.node;
      }
    }

    if (targetParentFound) {
      restored.parentId = targetParentFound.id;
      restored.level = targetParentFound.level + 1;
      targetParentFound.expanded = true;
      if (!targetParentFound.children) targetParentFound.children = [];
      targetParentFound.children.push(restored);
      mem.path = [...(findNodePathNames(targetParentFound.id) || []), targetParentFound.text].join(' / ');
    } else {
      const leftCount = appState.nodes.filter((n) => n.side === 'left').length;
      const rightCount = appState.nodes.filter((n) => n.side !== 'left').length;
      restored.parentId = 'root';
      restored.level = 1;
      restored.side = leftCount <= rightCount ? 'left' : 'right';
      restored.orderIndex = appState.nodes.length;
      appState.nodes.push(restored);
      mem.parentId = 'root';
      mem.level = 1;
      mem.path = '第 1 层主干任务';
    }

    // Update memory & descendant memory flags back to active on-tree
    mem.ended = false;
    mem.endedAt = null;
    mem.archivedWithParentId = null;

    appState.memories.forEach((m) => {
      if (m.archivedWithParentId === mem.id) {
        m.ended = false;
        m.endedAt = null;
        m.archivedWithParentId = null;
      }
    });

    newlyAnimatedNodeIds.add(restored.id);
    renderCanvas(false);
    saveState();
    if (currentView === 'list') renderTaskListView();
    if (currentView === 'memory') renderMemoryView();
    showToast(`🌱 「${restored.text}」已重新种回树上${targetParentFound ? `（恢复至「${targetParentFound.text}」下）` : '（已放回第 1 层）'}`);
  }

  // Delete single memory (only permanent way to remove a memory)
  function requestDeleteMemory(memoryId) {
    const mem = appState.memories.find((m) => m.id === memoryId);
    if (!mem) return;
    pendingDeleteMemoryId = memoryId;
    deleteMemoryModalDesc.textContent = `确认永久删除「${mem.text}」的回忆记录吗？此操作无法撤销${mem.ended ? '，且不会影响当前生长画布上的其他节点' : '（当前树上的任务节点不会被删除）'}。`;
    deleteMemoryConfirmModal.classList.remove('hidden');
  }

  function executeDeleteMemory(memoryId) {
    const idx = appState.memories.findIndex((m) => m.id === memoryId);
    if (idx === -1) return;
    const title = appState.memories[idx].text;
    appState.memories = appState.memories.filter(
      (m) => m.id !== memoryId && m.archivedWithParentId !== memoryId
    );
    deleteMemoryConfirmModal.classList.add('hidden');
    pendingDeleteMemoryId = null;
    saveState(appState, false);
    if (currentView === 'memory') renderMemoryView();
    if (currentView === 'list' && listFilter === 'ended') renderTaskListView();
    showToast(`已彻底删除回忆「${title}」`);
  }

  document.getElementById('btn-delete-memory-cancel').addEventListener('click', () => {
    deleteMemoryConfirmModal.classList.add('hidden');
    pendingDeleteMemoryId = null;
  });

  document.getElementById('btn-delete-memory-confirm').addEventListener('click', () => {
    if (pendingDeleteMemoryId) executeDeleteMemory(pendingDeleteMemoryId);
  });

  // =========================================================
  // CANVAS ZOOM & PAN + FOCUS MODE + AUTO FOCUS
  // =========================================================
  const viewport = document.getElementById('canvas-viewport');
  const world = document.getElementById('canvas-world');
  const btnZoomIn = document.getElementById('btn-zoom-in');
  const btnZoomOut = document.getElementById('btn-zoom-out');
  const btnZoomReset = document.getElementById('btn-zoom-reset');

  function applyCameraTransform(smooth = false) {
    world.style.transition = smooth
      ? 'transform 0.48s cubic-bezier(0.22, 1, 0.36, 1)'
      : 'none';
    world.style.transform = `translate3d(${camera.x.toFixed(1)}px, ${camera.y.toFixed(1)}px, 0) scale(${camera.scale.toFixed(3)})`;
    btnZoomReset.textContent = `${Math.round(camera.scale * 100)}%`;
  }

  function zoomToScale(newScale, focalClientX, focalClientY, smooth = false) {
    const clamped = Math.min(MAX_SCALE, Math.max(MIN_SCALE, newScale));
    if (focalClientX !== undefined && focalClientY !== undefined) {
      const rect = viewport.getBoundingClientRect();
      const centerX = rect.left + rect.width * 0.5;
      const centerY = rect.top + rect.height * 0.53;
      const vx = focalClientX - centerX;
      const vy = focalClientY - centerY;
      const scaleRatio = clamped / camera.scale;
      camera.x = vx - (vx - camera.x) * scaleRatio;
      camera.y = vy - (vy - camera.y) * scaleRatio;
    }
    camera.scale = clamped;
    applyCameraTransform(smooth);
  }

  function smoothPanToNode(node) {
    const targetScale = Math.max(camera.scale, node.level >= 3 ? 0.92 : 0.88);
    camera.scale = Math.min(MAX_SCALE, targetScale);
    camera.x = -node.position.x * camera.scale * 0.65;
    camera.y = -node.position.y * camera.scale * 0.65;
    applyCameraTransform(true);

    setTimeout(() => {
      const el = nodesLayer.querySelector(`[data-node-id="${node.id}"]`);
      if (el) {
        el.classList.add('highlight-focus');
        setTimeout(() => el.classList.remove('highlight-focus'), 2800);
      }
    }, 120);
  }

  const activePointers = new Map();
  let isPanningCanvas = false;
  let panStartX = 0;
  let panStartY = 0;
  let camStartX = 0;
  let camStartY = 0;
  let pinchStartDist = 0;
  let pinchStartScale = 1;
  let pinchStartCamX = 0;
  let pinchStartCamY = 0;
  let pinchMidClientX = 0;
  let pinchMidClientY = 0;
  let cameraRafPending = false;

  function scheduleCameraRender() {
    if (cameraRafPending) return;
    cameraRafPending = true;
    requestAnimationFrame(() => {
      cameraRafPending = false;
      applyCameraTransform(false);
    });
  }

  function clearSelectedNode() {
    if (selectedNodeId) {
      selectedNodeId = null;
      nodesLayer.querySelectorAll('.task-node-wrapper.is-selected').forEach((el) => el.classList.remove('is-selected'));
    }
  }

  viewport.addEventListener('pointerdown', (e) => {
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    if (
      e.target.closest('.task-node-wrapper') ||
      e.target.closest('.root-orb')
    ) {
      return;
    }
    closeAllFloatingMenus();
    clearSelectedNode();
    activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

    if (activePointers.size === 1) {
      isPanningCanvas = true;
      panStartX = e.clientX;
      panStartY = e.clientY;
      camStartX = camera.x;
      camStartY = camera.y;
      viewport.classList.add('dragging');
    } else if (activePointers.size === 2) {
      isPanningCanvas = false;
      const pts = Array.from(activePointers.values());
      pinchStartDist = Math.hypot(pts[1].x - pts[0].x, pts[1].y - pts[0].y) || 1;
      pinchStartScale = camera.scale;
      pinchStartCamX = camera.x;
      pinchStartCamY = camera.y;
      pinchMidClientX = (pts[0].x + pts[1].x) * 0.5;
      pinchMidClientY = (pts[0].y + pts[1].y) * 0.5;
    }
    try { viewport.setPointerCapture(e.pointerId); } catch (_) {}
  });

  viewport.addEventListener('pointermove', (e) => {
    if (!activePointers.has(e.pointerId)) return;
    activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

    if (activePointers.size === 2) {
      const pts = Array.from(activePointers.values());
      const curDist = Math.hypot(pts[1].x - pts[0].x, pts[1].y - pts[0].y) || 1;
      const curMidX = (pts[0].x + pts[1].x) * 0.5;
      const curMidY = (pts[0].y + pts[1].y) * 0.5;

      const targetScale = Math.min(MAX_SCALE, Math.max(MIN_SCALE, pinchStartScale * (curDist / pinchStartDist)));
      const rect = viewport.getBoundingClientRect();
      const centerX = rect.left + rect.width * 0.5;
      const centerY = rect.top + rect.height * 0.53;
      const vx = pinchMidClientX - centerX;
      const vy = pinchMidClientY - centerY;
      const scaleRatio = targetScale / pinchStartScale;

      camera.scale = targetScale;
      camera.x = vx - (vx - pinchStartCamX) * scaleRatio + (curMidX - pinchMidClientX);
      camera.y = vy - (vy - pinchStartCamY) * scaleRatio + (curMidY - pinchMidClientY);
      scheduleCameraRender();
      return;
    }

    if (isPanningCanvas && activePointers.size === 1) {
      camera.x = camStartX + (e.clientX - panStartX);
      camera.y = camStartY + (e.clientY - panStartY);
      scheduleCameraRender();
    }
  });

  function handleViewportPointerEnd(e) {
    activePointers.delete(e.pointerId);
    if (activePointers.size === 1) {
      const remaining = Array.from(activePointers.values())[0];
      isPanningCanvas = true;
      panStartX = remaining.x;
      panStartY = remaining.y;
      camStartX = camera.x;
      camStartY = camera.y;
    } else if (activePointers.size === 0) {
      isPanningCanvas = false;
      viewport.classList.remove('dragging');
    }
  }

  viewport.addEventListener('pointerup', handleViewportPointerEnd);
  viewport.addEventListener('pointercancel', handleViewportPointerEnd);

  viewport.addEventListener(
    'wheel',
    (e) => {
      e.preventDefault();
      const delta = -e.deltaY * 0.0012;
      const nextScale = camera.scale * (1 + delta);
      zoomToScale(nextScale, e.clientX, e.clientY, false);
    },
    { passive: false }
  );

  btnZoomIn.addEventListener('click', () => {
    zoomToScale(camera.scale + 0.15, undefined, undefined, true);
  });

  btnZoomOut.addEventListener('click', () => {
    zoomToScale(camera.scale - 0.15, undefined, undefined, true);
  });

  btnZoomReset.addEventListener('click', () => {
    camera.x = 0;
    camera.y = 0;
    camera.scale = isMobileViewport() ? 0.78 : 1;
    applyCameraTransform(true);
  });

  // Focus Mode ("专注模式")
  const btnFocusMode = document.getElementById('btn-focus-mode');

  function applyFocusModeUI() {
    const isFocus = Boolean(appState.focusMode);
    document.body.classList.toggle('focus-mode', isFocus);
    if (btnFocusMode) {
      btnFocusMode.classList.toggle('active', isFocus);
      btnFocusMode.setAttribute('aria-pressed', String(isFocus));
      btnFocusMode.title = isFocus
        ? '退出专注模式（恢复显示顶部导航与工具栏）'
        : '开启专注模式（隐藏顶部品牌栏、座右铭与工具栏）';
      const openEye = btnFocusMode.querySelector('.icon-eye-open');
      const focusEye = btnFocusMode.querySelector('.icon-eye-focus');
      if (openEye && focusEye) {
        openEye.classList.toggle('hidden', isFocus);
        focusEye.classList.toggle('hidden', !isFocus);
      }
    }
  }

  if (btnFocusMode) {
    btnFocusMode.addEventListener('click', (e) => {
      e.stopPropagation();
      appState.focusMode = !appState.focusMode;
      saveState();
      applyFocusModeUI();
      showToast(
        appState.focusMode
          ? '👁 已进入专注模式（再次点击右下角眼睛按钮可恢复显示）'
          : '✨ 已退出专注模式，恢复全部界面元素'
      );
    });
  }

  document.getElementById('btn-expand-all').addEventListener('click', () => {
    (function expandRec(list) {
      for (const n of list) {
        n._userDragged = false;
        if (n.children && n.children.length > 0) {
          n.expanded = true;
          n.children.forEach((c) => newlyAnimatedNodeIds.add(c.id));
          expandRec(n.children);
        }
      }
    })(appState.nodes);
    renderCanvas(false);
    saveState();
    camera.x = 0;
    camera.y = 0;
    zoomToScale(0.72, undefined, undefined, true);
    showToast('🌿 已展开全部层级的任务分支（自动防重叠布局）');
  });

  document.getElementById('btn-collapse-sub').addEventListener('click', () => {
    (function collapseRec(list) {
      for (const n of list) {
        n._userDragged = false;
        n.expanded = false;
        if (n.children && n.children.length > 0) collapseRec(n.children);
      }
    })(appState.nodes);
    renderCanvas(false);
    saveState();
    camera.x = 0;
    camera.y = 0;
    camera.scale = isMobileViewport() ? 0.78 : 1;
    applyCameraTransform(true);
    showToast('🌱 已收起深层分支，回到第 1 层主干视图');
  });

  document.getElementById('btn-add-root-task').addEventListener('click', () => {
    openAddChildModal('root');
  });

  // =========================================================
  // VIEW NAVIGATION: 生长画布 / 任务清单 / 回忆记录
  // =========================================================
  const navTabs = document.querySelectorAll('.nav-tab');
  const viewPanels = {
    canvas: document.getElementById('view-canvas'),
    list: document.getElementById('view-list'),
    memory: document.getElementById('view-memory')
  };

  function switchView(viewName) {
    currentView = viewName;
    navTabs.forEach((tab) => {
      tab.classList.toggle('active', tab.dataset.view === viewName);
    });
    Object.keys(viewPanels).forEach((k) => {
      viewPanels[k].classList.toggle('active', k === viewName);
    });

    if (viewName === 'canvas') renderCanvas();
    if (viewName === 'list') renderTaskListView();
    if (viewName === 'memory') renderMemoryView();
  }

  navTabs.forEach((tab) => {
    tab.addEventListener('click', () => {
      switchView(tab.dataset.view);
    });
  });

  // =========================================================
  // VIEW 2: 任务清单 (HIERARCHICAL TREE LIST + ENDED FILTER)
  // =========================================================
  const taskListContainer = document.getElementById('task-list-container');
  const listRootSummary = document.getElementById('list-root-summary');

  document.getElementById('list-filter-group').addEventListener('click', (e) => {
    const pill = e.target.closest('.filter-pill');
    if (!pill) return;
    listFilter = pill.dataset.filter;
    document
      .querySelectorAll('#list-filter-group .filter-pill')
      .forEach((b) => b.classList.toggle('active', b === pill));
    renderTaskListView();
  });

  document.getElementById('btn-list-add-l1').addEventListener('click', () => {
    openAddChildModal('root');
  });

  function renderTaskListView() {
    recalculateTreeStatuses(appState.nodes);
    listRootSummary.textContent = appState.rootText
      ? `当前核心念头：「${appState.rootText}」 — 第一性原理 1~4 层拆解清单`
      : '将庞大目标逐层拆解为最多 4 层可直接执行的最小动作';

    // Special filter: 'ended' shows archived ended tasks from memories
    if (listFilter === 'ended') {
      const endedMemories = appState.memories
        .filter((m) => m.ended && !m.archivedWithParentId)
        .sort((a, b) => (b.endedAt || b.completedAt) - (a.endedAt || a.completedAt));

      if (endedMemories.length === 0) {
        taskListContainer.innerHTML = `
          <div style="text-align:center;padding:48px 20px;color:#5b74a2;">
            <p style="font-size:16px;margin-bottom:8px;">暂无已结束的任务归档</p>
            <p style="font-size:13px;">在画布中右键点击「已完成」节点选择「结束此节点」后，可在此查看</p>
          </div>
        `;
        return;
      }

      taskListContainer.innerHTML = '';
      endedMemories.forEach((mem) => {
        const snap = mem.nodeSnapshot;
        const rows = [];
        if (snap) {
          (function flattenEnded(n, depth) {
            rows.push({ node: n, depth });
            if (n.children && n.children.length > 0) {
              n.children.forEach((c) => flattenEnded(c, depth + 1));
            }
          })(snap, 0);
        } else {
          rows.push({ node: { text: mem.text, level: mem.level, code: `L${mem.level}` }, depth: 0 });
        }

        rows.forEach(({ node, depth }, rIdx) => {
          const row = document.createElement('div');
          row.className = 'list-tree-item ended-archive';
          row.style.marginLeft = `${depth * 28}px`;
          const isRootOfArchive = rIdx === 0;
          row.innerHTML = `
            <div class="list-item-left">
              <img class="list-char-thumb" src="${CHAR_SPRITES.done}" alt="已结束" />
              <span class="list-level-tag">L${node.level || mem.level} · 已结束</span>
              <span class="list-task-title">${escapeHTML(node.text)}</span>
            </div>
            <div class="list-item-right">
              <span class="list-status-badge">🍂 ${formatTimestamp(mem.endedAt || mem.completedAt)}</span>
              ${isRootOfArchive ? '<button class="list-mini-btn btn-replant-list">🌱 重新种回</button>' : ''}
            </div>
          `;
          if (isRootOfArchive) {
            row.querySelector('.btn-replant-list').addEventListener('click', () => {
              replantMemory(mem.id);
              switchView('canvas');
            });
          }
          taskListContainer.appendChild(row);
        });
      });
      return;
    }

    const flatRows = [];
    (function flatten(list, ancestors = []) {
      for (const node of list) {
        const matchesFilter =
          listFilter === 'all' || node.status === listFilter;
        if (matchesFilter) {
          flatRows.push({ node, ancestors });
        }
        if (node.children && node.children.length > 0) {
          flatten(node.children, [...ancestors, node.text]);
        }
      }
    })(appState.nodes);

    if (flatRows.length === 0) {
      taskListContainer.innerHTML = `
        <div style="text-align:center;padding:48px 20px;color:#5b74a2;">
          <p style="font-size:16px;margin-bottom:8px;">当前筛选条件下暂无任务节点</p>
          <p style="font-size:13px;">可切换筛选标签或点击右上角「＋ 新增一级任务」</p>
        </div>
      `;
      return;
    }

    taskListContainer.innerHTML = '';
    flatRows.forEach(({ node }) => {
      const isParent = node.children && node.children.length > 0;
      const row = document.createElement('div');
      row.className = 'list-tree-item';
      row.style.marginLeft = `${(node.level - 1) * 28}px`;

      const statusText = isParent
        ? `${STATUS_LABELS[node.status]} (${node.progress.current}/${node.progress.total})${node.hasStuckDescendant ? ' · ⚡含受阻' : ''}`
        : STATUS_LABELS[node.status];

      row.innerHTML = `
        <div class="list-item-left">
          <img class="list-char-thumb" src="${CHAR_SPRITES[node.status]}" alt="${STATUS_LABELS[node.status]}" title="${isParent ? '父节点状态自动计算' : '点击切换状态'}" />
          <span class="list-level-tag">L${node.level} · ${node.code}</span>
          <span class="list-task-title">${escapeHTML(node.text)}</span>
        </div>
        <div class="list-item-right">
          <span class="list-status-badge">${statusText}</span>
          <button class="list-mini-btn btn-locate" title="在生长画布中定位到此节点">定位画布</button>
          <button class="list-mini-btn btn-sub ${node.level >= MAX_LEVEL ? 'disabled' : ''}" title="${node.level >= MAX_LEVEL ? '已达到最大拆解层级（最多 4 层）' : '新增下一层子任务'}">＋子任务</button>
          <button class="list-mini-btn btn-del" title="删除此节点">删除</button>
        </div>
      `;

      row.querySelector('.list-char-thumb').addEventListener('click', (e) => {
        e.stopPropagation();
        if (isParent) {
          showToast('父节点状态由子任务自动汇总计算');
        } else {
          openStatusPopover(node.id, e.clientX, e.clientY);
        }
      });

      row.querySelector('.btn-locate').addEventListener('click', () => {
        expandAncestorsOf(node.id);
        switchView('canvas');
        smoothPanToNode(node);
      });

      row.querySelector('.btn-sub').addEventListener('click', () => {
        if (node.level >= MAX_LEVEL) {
          showToast('已达到最大拆解层级（最多 4 层）');
          return;
        }
        openAddChildModal(node.id);
      });

      row.querySelector('.btn-del').addEventListener('click', () => {
        requestDeleteNode(node.id);
      });

      taskListContainer.appendChild(row);
    });
  }

  function expandAncestorsOf(targetId) {
    function helper(list) {
      for (const n of list) {
        if (n.id === targetId) return true;
        if (n.children && n.children.length > 0) {
          if (helper(n.children)) {
            n.expanded = true;
            return true;
          }
        }
      }
      return false;
    }
    helper(appState.nodes);
    saveState();
  }

  // =========================================================
  // VIEW 3: 回忆记录 (INDEPENDENT MEMORIES, SCHEME A STATS, DATE GROUPS)
  // =========================================================
  const memoryTimelineContainer = document.getElementById('memory-timeline-container');
  const memoryStatsBar = document.getElementById('memory-stats-bar');

  const memoryFilterGroup = document.getElementById('memory-filter-group');
  if (memoryFilterGroup) {
    memoryFilterGroup.addEventListener('click', (e) => {
      const pill = e.target.closest('.filter-pill');
      if (!pill) return;
      memoryFilter = pill.dataset.filter;
      memoryFilterGroup
        .querySelectorAll('.filter-pill')
        .forEach((b) => b.classList.toggle('active', b === pill));
      renderMemoryView();
    });
  }

  function getDateKey(ts) {
    const d = new Date(ts);
    const pad = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  }

  function getDateGroupLabel(dateKey) {
    const now = new Date();
    const todayKey = getDateKey(now.getTime());
    const yesterday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
    const yesterdayKey = getDateKey(yesterday.getTime());
    if (dateKey === todayKey) return '今天';
    if (dateKey === yesterdayKey) return '昨天';
    return dateKey;
  }

  function collectSnapshotSubItems(children, depth = 0, out = []) {
    if (!children || children.length === 0) return out;
    for (const c of children) {
      out.push({ text: c.text, level: c.level, status: c.status, depth });
      if (c.children && c.children.length > 0) {
        collectSnapshotSubItems(c.children, depth + 1, out);
      }
    }
    return out;
  }

  function renderMemoryView() {
    recalculateTreeStatuses(appState.nodes);
    syncDoneSnapshotsToMemories(appState);

    // Scheme A Statistics:
    // 1. 已开花节点 = ALL records in appState.memories (including ended)
    // 2. 最小动作完成数 & 整体生长率 = ONLY current active tree leaves (excluding ended)
    let totalLeaves = 0;
    let doneLeaves = 0;
    (function countActiveLeaves(list) {
      for (const n of list) {
        const isLeaf = !n.children || n.children.length === 0;
        if (isLeaf) {
          totalLeaves++;
          if (n.status === 'done') doneLeaves++;
        } else {
          countActiveLeaves(n.children);
        }
      }
    })(appState.nodes);

    const totalMemoriesCount = appState.memories.length;
    const rate = totalLeaves > 0 ? Math.round((doneLeaves / totalLeaves) * 100) : 0;

    memoryStatsBar.innerHTML = `
      <div class="memory-stat-card">
        <div class="stat-num">${totalMemoriesCount}</div>
        <div class="stat-label">已开花节点</div>
      </div>
      <div class="memory-stat-card">
        <div class="stat-num">${doneLeaves} / ${totalLeaves}</div>
        <div class="stat-label">最小动作完成数</div>
      </div>
      <div class="memory-stat-card">
        <div class="stat-num">${rate}%</div>
        <div class="stat-label">整体生长率</div>
      </div>
    `;

    // Filter memories for card display (collapse descendants archived under an ended parent card)
    const endedParentIds = new Set(
      appState.memories.filter((m) => m.ended && !m.archivedWithParentId).map((m) => m.id)
    );

    const visibleMemories = appState.memories.filter((m) => {
      if (m.ended && m.archivedWithParentId && endedParentIds.has(m.archivedWithParentId)) {
        return false;
      }
      const onTree = Boolean(findNodeById(m.id));
      if (memoryFilter === 'active') return !m.ended && onTree;
      if (memoryFilter === 'ended') return Boolean(m.ended);
      return true;
    });

    if (visibleMemories.length === 0) {
      memoryTimelineContainer.innerHTML = `
        <div style="text-align:center;padding:56px 20px;color:#5b74a2;">
          <img src="${CHAR_SPRITES.in_progress}" alt="加油" style="width:72px;opacity:0.85;margin-bottom:12px;" />
          <p style="font-size:16px;margin-bottom:6px;">${memoryFilter === 'all' ? '还没有已开花的回忆记录' : '当前筛选下暂无回忆卡片'}</p>
          <p style="font-size:13px;">在画布中将任务切换为「完成！」状态后，这里会独立留存每一次绽放</p>
        </div>
      `;
      return;
    }

    // Sort newest first & group by date (今天 / 昨天 / YYYY-MM-DD)
    const sorted = [...visibleMemories].sort((a, b) => {
      const ta = a.ended && a.endedAt ? a.endedAt : a.completedAt;
      const tb = b.ended && b.endedAt ? b.endedAt : b.completedAt;
      return tb - ta;
    });

    const groupsMap = new Map();
    sorted.forEach((m) => {
      const ts = m.ended && m.endedAt ? m.endedAt : m.completedAt;
      const dk = getDateKey(ts);
      if (!groupsMap.has(dk)) groupsMap.set(dk, []);
      groupsMap.get(dk).push(m);
    });

    memoryTimelineContainer.innerHTML = '';

    groupsMap.forEach((items, dateKey) => {
      const groupEl = document.createElement('div');
      groupEl.className = 'memory-date-group';

      const heading = document.createElement('div');
      heading.className = 'memory-date-heading';
      heading.innerHTML = `<span>${getDateGroupLabel(dateKey)}</span><span class="memory-date-count">${items.length} 条</span>`;
      groupEl.appendChild(heading);

      const grid = document.createElement('div');
      grid.className = 'memory-grid';

      items.forEach((mem) => {
        const treeMatch = findNodeById(mem.id);
        const onTree = Boolean(treeMatch);
        const card = document.createElement('div');
        card.className = `memory-card ${mem.ended ? 'is-ended' : ''}`;
        card.dataset.memoryId = mem.id;

        let tagHTML = '';
        if (mem.ended) {
          tagHTML = `<span class="memory-status-tag ended">🍂 已完成 · 已结束</span>`;
        } else if (onTree && treeMatch.node.status === 'done') {
          tagHTML = `<span class="memory-status-tag on-tree">🌸 仍在树上</span>`;
        } else if (onTree) {
          tagHTML = `<span class="memory-status-tag on-tree">🌸 仍在树上（状态已改）</span>`;
        } else {
          tagHTML = `<span class="memory-status-tag removed">🌸 仍在树上 · 原节点已删</span>`;
        }

        const subItems =
          mem.ended && mem.nodeSnapshot && mem.nodeSnapshot.children
            ? collectSnapshotSubItems(mem.nodeSnapshot.children)
            : [];
        const isSubExpanded = expandedMemorySubtrees.has(mem.id);

        card.innerHTML = `
          <div class="memory-card-top">
            <img class="memory-card-char" src="${CHAR_SPRITES.done}" alt="完成！" />
            <div class="memory-card-info">
              <div class="memory-card-tags">${tagHTML}</div>
              <div class="memory-card-path">L${mem.level} · ${escapeHTML(mem.path)}</div>
              <div class="memory-card-title">${escapeHTML(mem.text)}</div>
              <div class="memory-card-time">🌸 开花：${formatTimestamp(mem.completedAt)}</div>
              ${mem.ended && mem.endedAt ? `<div class="memory-card-time ended-time">🍂 结束：${formatTimestamp(mem.endedAt)}</div>` : ''}
            </div>
          </div>
          ${
            subItems.length > 0
              ? `
            <div class="memory-subtree-box">
              <button class="memory-subtree-toggle" type="button">
                <span>${isSubExpanded ? '▾' : '▸'} 查看已归档子任务（${subItems.length} 项）</span>
              </button>
              <div class="memory-subtree-list ${isSubExpanded ? '' : 'hidden'}">
                ${subItems
                  .map(
                    (s) =>
                      `<div class="memory-sub-item" style="padding-left:${s.depth * 14}px;"><span>✓</span><span>L${s.level} · ${escapeHTML(s.text)}</span></div>`
                  )
                  .join('')}
              </div>
            </div>
          `
              : ''
          }
          <div class="memory-card-footer">
            ${mem.ended ? '<button class="memory-card-btn replant" type="button">🌱 重新种回</button>' : ''}
            <button class="memory-card-btn danger delete-memory-btn" type="button">🗑 删除这条回忆</button>
          </div>
        `;

        if (subItems.length > 0) {
          const toggleBtn = card.querySelector('.memory-subtree-toggle');
          const listEl = card.querySelector('.memory-subtree-list');
          toggleBtn.addEventListener('click', () => {
            if (expandedMemorySubtrees.has(mem.id)) {
              expandedMemorySubtrees.delete(mem.id);
              listEl.classList.add('hidden');
              toggleBtn.querySelector('span').textContent = `▸ 查看已归档子任务（${subItems.length} 项）`;
            } else {
              expandedMemorySubtrees.add(mem.id);
              listEl.classList.remove('hidden');
              toggleBtn.querySelector('span').textContent = `▾ 收起已归档子任务（${subItems.length} 项）`;
            }
          });
        }

        const replantBtn = card.querySelector('.replant');
        if (replantBtn) {
          replantBtn.addEventListener('click', () => replantMemory(mem.id));
        }

        card.querySelector('.delete-memory-btn').addEventListener('click', () => {
          requestDeleteMemory(mem.id);
        });

        grid.appendChild(card);
      });

      groupEl.appendChild(grid);
      memoryTimelineContainer.appendChild(groupEl);
    });
  }

  // =========================================================
  // BACKUP: JSON EXPORT / IMPORT
  // =========================================================
  const btnExportJson = document.getElementById('btn-export-json');
  const btnImportJson = document.getElementById('btn-import-json');
  const inputImportJson = document.getElementById('input-import-json');

  if (btnExportJson) {
    btnExportJson.addEventListener('click', () => {
      const exportPayload = {
        version: 3,
        exportedAt: new Date().toISOString(),
        data: appState
      };
      const blob = new Blob([JSON.stringify(exportPayload, null, 2)], {
        type: 'application/json;charset=utf-8'
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `seed-todo-backup-${getDateKey(Date.now())}.json`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
      showToast('📤 已导出 JSON 备份文件');
    });
  }

  if (btnImportJson && inputImportJson) {
    btnImportJson.addEventListener('click', () => {
      inputImportJson.value = '';
      inputImportJson.click();
    });

    inputImportJson.addEventListener('change', (e) => {
      const file = e.target.files && e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = () => {
        try {
          const parsed = JSON.parse(String(reader.result || ''));
          const rawData = parsed && parsed.data && Array.isArray(parsed.data.nodes) ? parsed.data : parsed;
          if (!rawData || !Array.isArray(rawData.nodes)) {
            showToast('JSON 格式无效：缺少 nodes 任务数据');
            return;
          }
          appState = migrateState(rawData);
          saveState(appState, true);
          applyFocusModeUI();
          renderCanvas(false);
          if (currentView === 'list') renderTaskListView();
          if (currentView === 'memory') renderMemoryView();
          showToast(`📥 导入成功！共恢复 ${appState.nodes.length} 个主任务与 ${appState.memories.length} 条回忆`);
        } catch (err) {
          console.error(err);
          showToast('导入失败：请确认选择的是有效的 SEED JSON 备份文件');
        }
      };
      reader.readAsText(file, 'utf-8');
    });
  }

  // =========================================================
  // CELEBRATION PARTICLES & AMBIENT FLOATING LIGHT MOTES
  // =========================================================
  const celebrationLayer = document.getElementById('celebration-layer');

  function triggerCelebration(worldX, worldY, count = 22) {
    const colors = ['#ff9ebb', '#ffd966', '#7ce8d8', '#c8a8f0', '#96efb8'];
    for (let i = 0; i < count; i++) {
      const p = document.createElement('div');
      p.className = 'confetti-particle';
      const isStar = i % 3 === 0;
      const size = isStar ? 10 + (i % 5) : 7 + (i % 5);
      p.style.width = `${size}px`;
      p.style.height = `${size}px`;
      p.style.left = `${worldX}px`;
      p.style.top = `${worldY}px`;
      p.style.background = colors[i % colors.length];
      p.style.borderRadius = isStar ? '2px' : '50% 0 50% 50%';
      p.style.boxShadow = `0 0 8px ${colors[i % colors.length]}`;

      const angle = (Math.PI * 2 * i) / count + (Math.random() - 0.5) * 0.35;
      const dist = 48 + Math.random() * 68;
      p.style.setProperty('--tx', `${Math.cos(angle) * dist}px`);
      p.style.setProperty('--ty', `${Math.sin(angle) * dist - 18}px`);
      p.style.setProperty('--rot', `${Math.round(Math.random() * 260 - 130)}deg`);

      celebrationLayer.appendChild(p);
      setTimeout(() => p.remove(), 1100);
    }
  }

  function initAmbientParticles() {
    if (isMobileViewport() || (window.matchMedia && window.matchMedia('(pointer: coarse)').matches)) {
      return;
    }
    const container = document.getElementById('ambient-particles');
    if (!container) return;
    for (let i = 0; i < 24; i++) {
      const mote = document.createElement('div');
      mote.className = 'ambient-mote';
      const size = 3 + (i % 5);
      mote.style.width = `${size}px`;
      mote.style.height = `${size}px`;
      mote.style.left = `${(i * 4.1 + 3) % 96}%`;
      mote.style.top = `${(i * 11.7 + 8) % 92}%`;
      mote.style.animationDuration = `${7 + (i % 6) * 2}s`;
      mote.style.animationDelay = `-${(i * 1.3) % 9}s`;
      container.appendChild(mote);
    }
  }

  // =========================================================
  // UTILITIES & TOAST
  // =========================================================
  const toastContainer = document.getElementById('toast-container');

  function showToast(msg) {
    const el = document.createElement('div');
    el.className = 'seed-toast';
    el.textContent = msg;
    toastContainer.appendChild(el);
    setTimeout(() => {
      el.style.opacity = '0';
      el.style.transition = 'opacity 0.25s ease';
      setTimeout(() => el.remove(), 260);
    }, 2600);
  }

  function escapeHTML(str) {
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function formatTimestamp(ts) {
    const d = new Date(ts);
    const pad = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
  }

  initAmbientParticles();
  applyCameraTransform(false);
  applyFocusModeUI();
  renderCanvas();
})();
